const key=name=>name.toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(Boolean).sort().join(' ');
const aliases={
 'Ric Kovaleski':'Covaleski, Ric',
 'Joe Bruno':'Bruno, Joseph',
 'Len Silva':'Sliva, Len',
 'Steve Pisarchik':'Pesarchik, Steve',
 'Jason Koval':'Kovel, Jason',
 'Bryan Foytack':'Foytack, Brian'
};
// The earlier roster has Robert/Bob while this list has Bob/Bobby on Team 6.
// Do not infer which average belongs to which Johnson.
const ambiguous=new Set(['Robert Johnson','Bob Johnson'].map(key));
export function suppliedEnteringAverage(state,bowler){
 if(bowler.vacancy)return null;
 const team=state.teams.find(t=>t.players.includes(bowler.id))?.number||bowler.team||0;
 if(team===6&&ambiguous.has(key(bowler.name)))return null;
 const name=key(aliases[bowler.name]||bowler.name);
 const matches=BOWLER_LIST.filter(r=>key(r.sourceName)===name&&(!team||team===r.team));
 return matches.length===1&&Number.isFinite(matches[0].entering)?matches[0]:null;
}
export function applySuppliedEnteringAverages(state){
 const next=structuredClone(state),updated=[];
 for(const b of next.bowlers){
  if(Number.isFinite(b.entering))continue;
  const source=suppliedEnteringAverage(next,b);if(!source)continue;
  b.entering=source.entering;b.enteringSource=BOWLER_LIST_SOURCE;b.enteringSourceName=source.sourceName;
  updated.push(b.id);
 }
 return {state:next,updated};
}
